contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address newOwner) public payable {
        require(true);
        address before = c.owner();
        bool reverted;
        c.transferOwnership(newOwner);
        reverted = false;
        assert(!(before == address(0)) || (reverted == false ? c.owner() == newOwner : c.owner() == before));
    }
    receive() external payable {}
}

